package gadomancymodern.test;
import gadomancymodern.Gadomancy;
import gadomancymodern.aura.*;
import net.minecraft.core.*;
import net.minecraft.gametest.framework.*;
import net.minecraft.world.*;
import net.minecraft.world.effect.*;
import net.minecraft.world.entity.*;
import net.minecraft.world.entity.item.ItemEntity;
import net.minecraft.world.item.*;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.phys.*;
import net.minecraftforge.gametest.*;
import tc4revival.aspect.TCAspects;
import tc4revival.content.*;
@GameTestHolder("gadomancy") @PrefixGameTestTemplate(false)
public class AuraPylonServerTests {
    public static BlockPos build(GameTestHelper test){var base=test.absolutePos(new BlockPos(5,6,5));for(int y=0;y<4;y++)test.getLevel().setBlockAndUpdate(base.above(y),(y==3?Gadomancy.PYLON_CAP:Gadomancy.PYLON).get().defaultBlockState());return base;}
    public static void formed(GameTestHelper test,BlockPos base){for(int i=0;i<4;i++){var tile=(AuraPylonEntity)test.getLevel().getBlockEntity(base.above(i));tile.index=i;tile.formed=true;tile.changed();}}
    @GameTest(templateNamespace="gadomancy",template="test_empty")
    public static void wandActivationResearchSidedEssentiaAndSavedState(GameTestHelper test){var level=test.getLevel();var base=build(test);var player=new net.minecraftforge.common.util.FakePlayer(level,new com.mojang.authlib.GameProfile(java.util.UUID.randomUUID(),"GadPylon"));var wand=TCItems.CASTING_WAND.get().create(WandParts.Rod.SILVERWOOD_STAFF,WandParts.Cap.GOLD,false,true);player.setItemInHand(InteractionHand.MAIN_HAND,wand);test.assertTrue(!AuraPylonBlock.form(level,base.above(3),player,InteractionHand.MAIN_HAND),"Undiscovered research blocks formation");thaumcraft.api.ThaumcraftApiHelper.completeResearch(player,"gadomancy:aura_pylon");var aspect=TCAspects.catalog().require("aer");int vis=TCItems.CASTING_WAND.get().vis(wand,aspect);test.assertTrue(AuraPylonBlock.form(level,base.above(3),player,InteractionHand.MAIN_HAND),"Four actual pylon blocks form with charged wand");test.assertTrue(vis-TCItems.CASTING_WAND.get().vis(wand,aspect)==15000,"Formation consumes 150 vis in each primal");var input=(AuraPylonEntity)level.getBlockEntity(base);var master=input.section(2);var essence=new HeldEssenceEntity(level,master.getBlockPos(),TCItems.WISP_ESSENCE.get().of(aspect));master.heartbeat(essence);test.assertTrue(input.suction(Direction.DOWN)==64&&input.connectable(Direction.DOWN)&&!input.connectable(Direction.NORTH)&&!input.canOutput(Direction.DOWN),"Only bottom has the original input-only suction 64");test.assertTrue(input.addEssentia(aspect,40,Direction.DOWN)==15&&input.amount==15,"Three sections hold a total of 15 essentia");test.assertTrue(input.addEssentia(TCAspects.catalog().require("ignis"),1,Direction.DOWN)==0&&master.addEssentia(aspect,1,Direction.DOWN)==0,"Crystal aspect and physical input section restrict transfer");var restored=new AuraPylonEntity(base,input.getBlockState());restored.load(input.saveWithoutMetadata());test.assertTrue(restored.formed&&restored.index==0&&restored.amount==15&&restored.aspect.equals("aer"),"Structure and essentia persist");test.succeed();}
    @GameTest(templateNamespace="gadomancy",template="test_empty",timeoutTicks=100)
    public static void heldEssenceIsPhysicalAndRemovalClearsStoredEssentia(GameTestHelper test){var level=test.getLevel();var base=build(test);formed(test,base);var master=(AuraPylonEntity)level.getBlockEntity(base.above(2));var crystal=TCItems.WISP_ESSENCE.get().of(TCAspects.catalog().require("aer"));var drop=new ItemEntity(level,master.crystalPosition().x,master.crystalPosition().y,master.crystalPosition().z,crystal.copyWithCount(2));drop.setNoGravity(true);drop.setDeltaMovement(Vec3.ZERO);level.addFreshEntity(drop);test.runAfterDelay(5,()->{var held=level.getEntitiesOfClass(HeldEssenceEntity.class,new AABB(base).inflate(5));test.assertTrue(held.size()==1&&held.get(0).getItem().getCount()==1&&drop.getItem().getCount()==1,"Exactly one essence is captured while a remaining stack stays physical");test.assertTrue(held.get(0).position().distanceToSqr(master.crystalPosition())<.0001,"Crystal hovers at the legacy midpoint height");drop.discard();var input=master.section(0);input.addEssentia(TCAspects.catalog().require("aer"),10,Direction.DOWN);held.get(0).discard();});test.runAfterDelay(20,()->{test.assertTrue(master.aspect.isEmpty()&&master.observedCrystal.isEmpty()&&master.section(0).amount==0,"Removing the actual item clears selection and buffered essentia after heartbeat timeout");test.succeed();});}
    @GameTest(templateNamespace="gadomancy",template="test_empty",timeoutTicks=100)
    public static void towerConsumesAndDistributesThenBreakReleasesOneCrystal(GameTestHelper test){var level=test.getLevel();var base=build(test);formed(test,base);var master=(AuraPylonEntity)level.getBlockEntity(base.above(2));var held=new HeldEssenceEntity(level,master.getBlockPos(),TCItems.WISP_ESSENCE.get().of(TCAspects.catalog().require("aer")));level.addFreshEntity(held);master.heartbeat(held);master.section(0).addEssentia(TCAspects.catalog().require("aer"),5,Direction.DOWN);var cow=EntityType.COW.create(level);cow.setPos(base.getCenter().add(3,2,0));cow.setNoAi(true);cow.setNoGravity(true);level.addFreshEntity(cow);test.runAfterDelay(33,()->{test.assertTrue(master.section(0).amount==4&&cow.hasEffect(MobEffects.MOVEMENT_SPEED)&&cow.getEffect(MobEffects.MOVEMENT_SPEED).getAmplifier()==1,"One essentia per 32 ticks drives actual Aer speed II");level.removeBlock(base.above(1),false);});test.runAfterDelay(55,()->{test.assertTrue(!held.isAlive(),"Invalid tower releases held entity");var dropped=level.getEntitiesOfClass(ItemEntity.class,new AABB(base).inflate(8),e->e.isAlive()&&e.getItem().is(TCItems.WISP_ESSENCE.get()));test.assertTrue(dropped.size()==1&&dropped.get(0).getItem().getCount()==1,"Structure removal returns one original crystal, without duplicate stored copies");cow.discard();test.succeed();});}
    @GameTest(templateNamespace="gadomancy",template="test_empty")
    public static void potionCapsSpecialEffectsAndDamageProjectiles(GameTestHelper test){var level=test.getLevel();var at=test.absolutePos(new BlockPos(4,80,4));var cow=EntityType.COW.create(level);cow.setPos(at.getCenter());for(int i=0;i<2000;i++)StandardAuraEffects.extend(cow,MobEffects.MOVEMENT_SPEED,7200,6,1,true);test.assertTrue(cow.getEffect(MobEffects.MOVEMENT_SPEED).getDuration()==7200,"Repeated aura cannot exceed the original cap");cow.addEffect(new MobEffectInstance(GadEffects.VIS_AFFINITY.get(),100,1));test.assertTrue(Math.abs(cow.getAttributeValue(TCAttributes.VIS_COST.get())-.84)<.00001,"Magic aura has the actual 16 percent vis discount at level II");var arrow=new net.minecraft.world.entity.projectile.Arrow(level,at.getX()+1,at.getY(),at.getZ());arrow.setDeltaMovement(1,0,0);level.addFreshEntity(arrow);double previous=arrow.getX();GadEffects.ACHROMATIC.get().applyEffectTick(cow,0);test.assertTrue(arrow.getX()>previous,"Achromatic potion moves actual arrows through and past the holder");arrow.discard();var sheep=EntityType.SHEEP.create(level);sheep.setBaby(true);for(int i=0;i<1000&&sheep.isBaby();i++)AuraEffectRegistry.effects().get("victus").entity(level,at,sheep);test.assertTrue(!sheep.isBaby(),"Victus changes actual animal age");sheep.setSheared(true);for(int i=0;i<1000&&sheep.isSheared();i++)AuraEffectRegistry.effects().get("pannus").entity(level,at,sheep);test.assertTrue(!sheep.isSheared(),"Pannus restores actual wool");test.succeed();}
    @GameTest(templateNamespace="gadomancy",template="test_empty")
    public static void auraResearchPagesOnlyExposeObservedEffects(GameTestHelper test){var pages=tc4revival.research.ResearchPages.bundled();var none=pages.visible("gadomancy:aura_effects",key->false,java.util.Map.of());test.assertTrue(none.size()==1,"Before observation only the introduction exists");var known=java.util.Set.of("gadomancy:aura/aer","gadomancy:aura/aqua","gadomancy:aura/terra","gadomancy:aura/ignis","gadomancy:aura/ordo");var visible=pages.visible("gadomancy:aura_effects",known::contains,java.util.Map.of());test.assertTrue(visible.size()==3,"Five discoveries append two real navigable research pages");test.assertTrue(((tc4revival.research.ResearchPage.Custom)visible.get(1).recipe()).data().getAsJsonArray("aspects").size()==4,"Original four effects per page");test.assertTrue(AuraEffectRegistry.effects().size()==41,"All forty-one original aura aspects registered");test.succeed();}
    @GameTest(templateNamespace="gadomancy",template="test_empty")
    public static void miningLuckAndGolemBuffModifyActualAttributesAndRestore(GameTestHelper test){var level=test.getLevel();var player=NodeServerTests.player(test);var stack=new ItemStack(Items.DIAMOND_PICKAXE);stack.enchant(net.minecraft.world.item.enchantment.Enchantments.BLOCK_FORTUNE,1);player.setItemInHand(InteractionHand.MAIN_HAND,stack);java.util.List<net.minecraft.server.level.ServerPlayer> players=net.minecraftforge.fml.util.ObfuscationReflectionHelper.getPrivateValue(net.minecraft.server.players.PlayerList.class,level.getServer().getPlayerList(),"f_11196_");players.add(player);try{test.assertTrue(stack.getEnchantmentLevel(net.minecraft.world.item.enchantment.Enchantments.BLOCK_FORTUNE)==1,"No potion leaves actual Forge enchantment lookup unchanged");player.addEffect(new MobEffectInstance(GadEffects.LUCK.get(),100,1));test.assertTrue(stack.getEnchantmentLevel(net.minecraft.world.item.enchantment.Enchantments.BLOCK_FORTUNE)==3&&stack.getEnchantmentLevel(net.minecraft.world.item.enchantment.Enchantments.MOB_LOOTING)==2,"Lucrum II augments Fortune and Looting through actual ItemStack API");test.assertTrue(stack.getEnchantmentLevel(net.minecraft.world.item.enchantment.Enchantments.BLOCK_EFFICIENCY)==0,"Unrelated enchantment remains unchanged");player.removeEffect(GadEffects.LUCK.get());test.assertTrue(stack.getEnchantmentLevel(net.minecraft.world.item.enchantment.Enchantments.BLOCK_FORTUNE)==1,"Potion expiry restores original enchantment");}finally{players.remove(player);}var golem=Gadomancy.SILVERWOOD_ENTITY.get().create(level);double speed=golem.getAttributeValue(net.minecraft.world.entity.ai.attributes.Attributes.MOVEMENT_SPEED),health=golem.getMaxHealth(),damage=golem.getAttributeValue(net.minecraft.world.entity.ai.attributes.Attributes.ATTACK_DAMAGE);golem.addEffect(new MobEffectInstance(GadEffects.GOLEM.get(),100,0));test.assertTrue(Math.abs(golem.getAttributeValue(net.minecraft.world.entity.ai.attributes.Attributes.MOVEMENT_SPEED)-speed*1.4)<.00001&&Math.abs(golem.getMaxHealth()-health*1.5)<.00001&&Math.abs(golem.getAttributeValue(net.minecraft.world.entity.ai.attributes.Attributes.ATTACK_DAMAGE)-damage*2)<.00001,"Actual golem gains original movement/health/attack multipliers");golem.removeEffect(GadEffects.GOLEM.get());test.assertTrue(golem.getMaxHealth()==health&&golem.getAttributeValue(net.minecraft.world.entity.ai.attributes.Attributes.MOVEMENT_SPEED)==speed,"Buff removal restores original attributes");test.succeed();}
}
